const rows = $input.all().map(item => item.json);

if (rows.length === 0) {
  throw new Error(
    'В PostgreSQL не найдены сообщения этого диалога'
  );
}

// Запись задания/собеседника из Airtable
const assistantRecord =
  $('Get a record').first().json;

/**
 * Имя собеседника
 */
const userName = String(
  assistantRecord.person_name ??
  assistantRecord.telegram_username ??
  rows[0]?.tg_name ??
  'Пользователь'
)
  .replace(/^@/, '')
  .trim();

/**
 * Имя ассистента
 */
const assistantInfo =
  assistantRecord.assistant_info ??
  assistantRecord['assistant_ info'] ??
  'Ассистент';

const assistantName =
  String(assistantInfo)
    .split(',')[0]
    .trim() || 'Ассистент';

/**
 * Номер задачи
 */
const taskNumber =
  assistantRecord.task_number ??
  'unknown';

/**
 * Проверка, что поле содержит реальный текст
 */
function hasText(value) {
  if (value === null || value === undefined) {
    return false;
  }

  const text = String(value).trim();

  return (
    text !== '' &&
    text !== '-' &&
    text.toLowerCase() !== 'null' &&
    text.toLowerCase() !== 'undefined'
  );
}

/**
 * Поддержка обоих названий колонки:
 * user_message_date
 * user_message_data
 */
function getUserMessageDate(row) {
  return (
    row.user_message_date ??
    row.user_message_data ??
    null
  );
}

/**
 * Поддержка возможных вариантов названия даты ответа
 */
function getBotMessageDate(row) {
  return (
    row.bot_message_date ??
    row.bot_message_data ??
    null
  );
}

/**
 * Преобразование даты в timestamp
 */
function getTimestamp(value) {
  if (!value) {
    return null;
  }

  const parsed = new Date(value);
  const timestamp = parsed.getTime();

  return Number.isFinite(timestamp)
    ? timestamp
    : null;
}

/**
 * Форматирование даты по Москве
 */
const dateFormatter = new Intl.DateTimeFormat(
  'ru-RU',
  {
    timeZone: 'Europe/Moscow',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
  }
);

function formatDate(value) {
  if (!value) {
    return '';
  }

  const parsed = new Date(value);

  if (!Number.isFinite(parsed.getTime())) {
    return '';
  }

  return dateFormatter.format(parsed);
}

/**
 * Создаём отдельное событие для каждого сообщения.
 * Затем сортируем все события по реальному времени.
 */
const events = [];
const seenMessages = new Set();

function addEvent({
  role,
  speaker,
  text,
  date,
  rowId,
  order,
}) {
  if (!hasText(text)) {
    return;
  }

  const normalizedText = String(text).trim();

  /*
   * Не используем Telegram message_id для удаления дублей,
   * потому что в старых строках он может повторяться.
   */
  const uniqueKey = [
    role,
    rowId ?? '',
    date ?? '',
    normalizedText,
  ].join('|');

  if (seenMessages.has(uniqueKey)) {
    return;
  }

  seenMessages.add(uniqueKey);

  events.push({
    role,
    speaker,
    text: normalizedText,
    date,
    timestamp: getTimestamp(date),
    rowId: Number(rowId ?? 0),
    order,
  });
}

for (const row of rows) {
  addEvent({
    role: 'user',
    speaker: userName,
    text: row.user_message_text,
    date: getUserMessageDate(row),
    rowId: row.id,
    order: 0,
  });

  addEvent({
    role: 'assistant',
    speaker: assistantName,
    text: row.bot_message_text,
    date: getBotMessageDate(row),
    rowId: row.id,
    order: 1,
  });
}

if (events.length === 0) {
  throw new Error(
    'Строки найдены, но в них отсутствует текст сообщений'
  );
}

/**
 * Сортируем сообщения по реальному времени.
 *
 * При одинаковом времени:
 * 1. сортируем по ID строки;
 * 2. сначала пользователь, затем ассистент.
 */
events.sort((a, b) => {
  if (
    a.timestamp !== null &&
    b.timestamp !== null &&
    a.timestamp !== b.timestamp
  ) {
    return a.timestamp - b.timestamp;
  }

  if (
    a.timestamp !== null &&
    b.timestamp === null
  ) {
    return -1;
  }

  if (
    a.timestamp === null &&
    b.timestamp !== null
  ) {
    return 1;
  }

  if (a.rowId !== b.rowId) {
    return a.rowId - b.rowId;
  }

  return a.order - b.order;
});

/**
 * Формируем сообщения без вступительного блока.
 */
const dialogParts = events.map(event => {
  const formattedDate = formatDate(event.date);

  const title = formattedDate
    ? `[${formattedDate}] ${event.speaker}:`
    : `${event.speaker}:`;

  return `${title}\n${event.text}`;
});

const dialogText = dialogParts.join(
  '\n\n----------------------------------------\n\n'
);

/**
 * BOM нужен для правильного отображения русского текста
 * при открытии TXT-файла.
 */
const fileContent =
  '\uFEFF' + dialogText;

/**
 * Безопасное имя файла
 */
function safeFilePart(value) {
  return String(value)
    .trim()
    .replace(/[<>:"/\\|?*\u0000-\u001F]/g, '_')
    .replace(/\s+/g, '_')
    .slice(0, 60);
}

const datePart = new Date()
  .toISOString()
  .slice(0, 10);

const fileName =
  `dialog_${safeFilePart(taskNumber)}` +
  `_${safeFilePart(userName)}` +
  `_${datePart}.txt`;

return [
  {
    json: {
      record_id: assistantRecord.id,

      task_number: taskNumber,
      user_name: userName,
      assistant_name: assistantName,

      messages_count: events.length,

      dialog_text: dialogText,

      file_base64: Buffer
        .from(fileContent, 'utf8')
        .toString('base64'),

      file_name: fileName,

      content_type:
        'text/plain; charset=utf-8',
    },
  },
];
